nextflow_process {

    name "Test Process HAMRONIZATION_AMRFINDERPLUS"
    script "../main.nf"
    process "HAMRONIZATION_AMRFINDERPLUS"

    tag "modules"
    tag "modules_nfcore"
    tag "hamronization"
    tag "hamronization/amrfinderplus"

    test("hamronization/amrfinderplus - delete_me/amrfinderplus - tsv") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'delete_me/amrfinderplus/test_output_prot.tsv', checkIfExists: true)
                ]
                input[1] = 'tsv'
                input[2] = '4.0.23'
                input[3] = '2025-07-16.1'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("hamronization/amrfinderplus - delete_me/amrfinderplus - tsv - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file("https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/delete_me/amrfinderplus/test_output_prot.tsv", checkIfExists: true)
                ]
                input[1] = 'tsv'
                input[2] = '4.0.23'
                input[3] = '2025-07-16.1'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

}
